import React, { useState, useEffect } from 'react';
import { publicAPI, apiCall } from '../services/apiService';
import './PublicVendors.css';

const PublicVendors = () => {
  const [vendors, setVendors] = useState([]);
  const [filteredVendors, setFilteredVendors] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [filters, setFilters] = useState({
    region: '',
    cuisine: ''
  });

  useEffect(() => {
    fetchVendors();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [vendors, filters]);

  const fetchVendors = async () => {
    setIsLoading(true);
    setError('');

    const result = await apiCall(publicAPI.getAllVendors);

    if (result.success) {
      setVendors(result.data || []);
    } else {
      setError(result.error);
    }

    setIsLoading(false);
  };

  const applyFilters = () => {
    let filtered = [...vendors];

    if (filters.region) {
      filtered = filtered.filter(vendor => 
        vendor.operatingRegion?.toLowerCase().includes(filters.region.toLowerCase())
      );
    }

    if (filters.cuisine) {
      filtered = filtered.filter(vendor => 
        vendor.cuisineSpecialties?.toLowerCase().includes(filters.cuisine.toLowerCase())
      );
    }

    setFilteredVendors(filtered);
  };

  const handleFilterChange = (filterType, value) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
  };

  const clearFilters = () => {
    setFilters({
      region: '',
      cuisine: ''
    });
  };

  const getUniqueValues = (field) => {
    const values = vendors
      .map(vendor => vendor[field])
      .filter(value => value)
      .flatMap(value => value.split(',').map(item => item.trim()))
      .filter(item => item);
    
    return [...new Set(values)];
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading vendors...
      </div>
    );
  }

  return (
    <div className="public-vendors">
      <div className="page-header">
        <div className="container">
          <h1>Food Truck Vendors</h1>
          <p>Discover amazing food trucks in Chennai and Bangalore</p>
        </div>
      </div>

      <div className="container">
        {error && (
          <div className="alert alert-error">
            {error}
          </div>
        )}

        {/* Filters Section */}
        <div className="filters-section">
          <div className="filters-header">
            <h2>Find Your Perfect Food Truck</h2>
            <button 
              onClick={clearFilters} 
              className="btn btn-secondary btn-sm"
              disabled={!filters.region && !filters.cuisine}
            >
              Clear Filters
            </button>
          </div>

          <div className="filters-grid">
            <div className="filter-group">
              <label className="filter-label">Region</label>
              <select
                value={filters.region}
                onChange={(e) => handleFilterChange('region', e.target.value)}
                className="form-control filter-select"
              >
                <option value="">All Regions</option>
                {getUniqueValues('operatingRegion').map(region => (
                  <option key={region} value={region}>{region}</option>
                ))}
              </select>
            </div>

            <div className="filter-group">
              <label className="filter-label">Cuisine Type</label>
              <select
                value={filters.cuisine}
                onChange={(e) => handleFilterChange('cuisine', e.target.value)}
                className="form-control filter-select"
              >
                <option value="">All Cuisines</option>
                {getUniqueValues('cuisineSpecialties').map(cuisine => (
                  <option key={cuisine} value={cuisine}>{cuisine}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Results Summary */}
        <div className="results-summary">
          <p>
            Showing {filteredVendors.length} of {vendors.length} food trucks
            {(filters.region || filters.cuisine) && (
              <span className="filter-summary">
                {filters.region && ` in ${filters.region}`}
                {filters.region && filters.cuisine && ','}
                {filters.cuisine && ` serving ${filters.cuisine}`}
              </span>
            )}
          </p>
        </div>

        {/* Vendors Grid */}
        {filteredVendors.length === 0 ? (
          <div className="no-results">
            <div className="no-results-icon">🚚</div>
            <h3>No Food Trucks Found</h3>
            <p>
              {vendors.length === 0 
                ? "No vendors are currently registered."
                : "Try adjusting your filters to see more results."
              }
            </p>
            {(filters.region || filters.cuisine) && (
              <button onClick={clearFilters} className="btn btn-primary">
                Show All Vendors
              </button>
            )}
          </div>
        ) : (
          <div className="vendors-grid">
            {filteredVendors.map(vendor => (
              <VendorCard key={vendor.id} vendor={vendor} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

const VendorCard = ({ vendor }) => {
  return (
    <div className="vendor-card">
      <div className="vendor-header">
        <h3 className="vendor-name">{vendor.name}</h3>
        <span className="vendor-region">{vendor.operatingRegion}</span>
      </div>

      <div className="vendor-body">
        {vendor.cuisineSpecialties && (
          <div className="vendor-info">
            <strong>Cuisines:</strong>
            <div className="cuisine-tags">
              {vendor.cuisineSpecialties.split(',').map((cuisine, index) => (
                <span key={index} className="cuisine-tag">
                  {cuisine.trim()}
                </span>
              ))}
            </div>
          </div>
        )}

        {vendor.description && (
          <div className="vendor-info">
            <strong>About:</strong>
            <p>{vendor.description}</p>
          </div>
        )}

        {vendor.contactNumber && (
          <div className="vendor-info">
            <strong>Contact:</strong>
            <p>{vendor.contactNumber}</p>
          </div>
        )}

        {vendor.email && (
          <div className="vendor-info">
            <strong>Email:</strong>
            <p>{vendor.email}</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PublicVendors;
